/bin/bash -lc "python - <<'PY'
import sim, mujoco, numpy as np
s=sim.Sim()
for name in ['hand','panda_hand','panda_link8','ee','gripper','right_finger','left_finger']:
    try:
        sid=mujoco.mj_name2id(s.model,mujoco.mjtObj.mjOBJ_BODY,name)
        print('body',name,sid,'xpos',s.data.xpos[sid])
    except Exception as e:
        pass
PY"

